$ErrorActionPreference='Stop'
$code=[System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
$tokens=$null;$parseErrors=$null
[void][System.Management.Automation.Language.Parser]::ParseInput($code,[ref]$tokens,[ref]$parseErrors)
[PSCustomObject]@{Characters=$code.Length;TokenCount=@($tokens).Count;Errors=@($parseErrors|ForEach-Object {[PSCustomObject]@{Message=$_.Message;Line=$_.Extent.StartLineNumber;Column=$_.Extent.StartColumnNumber;Text=$_.Extent.Text}})}|ConvertTo-Json -Depth 5
if(@($parseErrors).Count -gt 0){exit 1}
